fn is_palindrome(text: Vec<char>) -> bool {
    let len = text.len();
    for i in 0..len / 2 {
        let left_char = text[i];
        let right_char = text[len - 1 - i];

        if left_char.to_ascii_lowercase() != right_char.to_ascii_lowercase() {
            return false;
        }
    }
    true
}

fn main() {
    // Example usage
    let text1: Vec<char> = vec!['A', 'b', 'C', 'c', 'b', 'a', 'A'];
    let text2: Vec<char> = vec!['A', 'b', 'C', 'c', 'b', 'a', 'B'];

    println!("{}", is_palindrome(text1)); // true
    println!("{}", is_palindrome(text2)); // false
}